const data = JSON.parse($input.first().json["omImage "]);
const base64Data = data.url.split(',')[1];
const buffer = Buffer.from(base64Data, 'base64');

return  [{
  json: {},
  binary: {
    data: {
      mimeType: 'image/png',
      fileName: 'ai_image.png',
      fileExtension: 'png',
      data: buffer,
    }
  }
}];

// The studio's own run STATUS is PARTIAL whenever a requested type is unavailable, so the
// asset's status is what this branches on. The LinkedIn branch asks the studio for the
// composer-authored GIF type; both animated opt-ins (ANIMATED, AGENT) share it.
const r = $input.first().json || {};
const assets = r.ASSETS || [];
const req = $('select_article_to_post').first().json;
const want = 'animation_linkedin';
const a = assets.find((x) => x.ASSET_TYPE === want) || null;
const ok = Boolean(a && a.STATUS === 'RENDERED' && a.IMAGE);
return [{ json: {
  RUN_ID: r.RUN_ID || '',
  RUN_STATUS: r.STATUS || '',
  ASSET_TYPE: a ? a.ASSET_TYPE : '',
  ASSET_STATUS: a ? a.STATUS : 'MISSING',
  CONTENT_TYPE: a ? (a.CONTENT_TYPE || '') : '',
  IMAGE: a && a.IMAGE ? a.IMAGE : '',
  DURATION_MS: a ? (a.DURATION_MS || '') : '',
  FRAME_COUNT: a ? (a.FRAME_COUNT || '') : '',
  ERROR: ok ? '' : ('animated media unavailable: ' + ((a && (a.ERROR || a.STATUS)) || 'no asset returned')),
} }];

const a = $input.first().json || {};
const url = String(a.IMAGE || '');
if (!url.startsWith('data:')) throw new Error('no animation data URL to publish');
const i = url.indexOf(',');
const ext = a.CONTENT_TYPE === 'image/gif' ? 'gif' : (a.CONTENT_TYPE === 'image/webp' ? 'webp' : 'png');
return [{ json: { CONTENT_TYPE: a.CONTENT_TYPE, ASSET_TYPE: a.ASSET_TYPE, RUN_ID: a.RUN_ID,
  DURATION_MS: a.DURATION_MS, FRAME_COUNT: a.FRAME_COUNT },
  binary: { data: { data: Buffer.from(url.slice(i + 1), 'base64'), mimeType: a.CONTENT_TYPE,
    fileName: 'animated_infographic.' + ext, fileExtension: ext } } }];

